const pricingPlans = [
  {
    id: "basic",
    name: "Basic",
    price: "£70",
    description: "For professionals needing sharper positioning, fast.",
    features: [
      "CV Revamp",
      "LinkedIn Optimization"
    ],
    isMostPopular: false
  },
  {
    id: "premium",
    name: "Premium",
    price: "£250",
    description: "For professionals tired of applying blindly.",
    features: [
      "CV Revamp",
      "LinkedIn Optimization",
      "Job Application Services",
      "3 Guaranteed Interviews",
      "2025 Job roadmap handbook"
    ],
    isMostPopular: true
  },
  {
    id: "comprehensive",
    name: "Comprehensive Plan",
    price: "£350",
    description: "For professionals serious about securing offers.",
    features: [
      "Everything in Premium",
      "5 Guaranteed Interviews",
      "Interview Prep Sessions",
      "Salary Negotiation Support"
    ],
    isMostPopular: false
  },
  {
    id: "platinum",
    name: "Platinum Plan",
    price: "£200",
    description: "For high-level executives seeking tailored strategy.",
    features: [
      "Everything in Comprehensive",
      "Executive Resume Writing",
      "Personal Branding Strategy",
      "Direct Recruiter Connections"
    ],
    isMostPopular: false
  }
];

export default function V1PricingSection({ onStartNow }: V1PricingSectionProps) {
  const [selectedPlan, setSelectedPlan] = useState("premium");
  const [hoveredPlan, setHoveredPlan] = useState<string | null>(null);

  const activePlan = pricingPlans.find(plan => plan.id === selectedPlan) || pricingPlans[1];

  const handleStartNow = () => {
    if (onStartNow) {
      onStartNow(selectedPlan);
    }
  };

  return (
    <section className="relative py-20 lg:py-32">
      <div className="max-w-[1400px] mx-auto px-3 lg:px-6">
        {/* Section Heading */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          viewport={{ once: true }}
          className="text-center mb-6"
        >
          <h2 className="text-4xl lg:text-6xl font-mona-sans font-bold leading-tight mb-4">
            <span className="text-white">CHOOSE YOUR </span>
            <span className="text-[#A2CE3A]">ACCELERATION TIER.</span>
          </h2>
          <p className="text-white/40 font-sora text-sm">
            Transparent pricing. No fake guarantees. Every package is built around the outcome you actually need.
          </p>
        </motion.div>

        {/* Pricing Container */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          viewport={{ once: true }}
          className="rounded-[24px] p-6 lg:p-10"
          style={{ background: "#1E1F2180" }}
        >
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Left Side - Pricing Cards */}
            <div className="lg:col-span-2 space-y-4">
              {pricingPlans.map((plan, index) => (
                <motion.div
                  key={plan.id}
                  initial={{ opacity: 0, x: -30 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.6, delay: index * 0.1 }}
                  viewport={{ once: true }}
                  onClick={() => setSelectedPlan(plan.id)}
                  onMouseEnter={() => setHoveredPlan(plan.id)}
                  onMouseLeave={() => setHoveredPlan(null)}
                  className="rounded-[28px] p-6 cursor-pointer transition-all duration-500 ease-in-out relative"
                  style={{
                    background: selectedPlan === plan.id || hoveredPlan === plan.id
                      ? "linear-gradient(135deg, rgba(162, 206, 58, 0.2) 0%, rgba(21, 99, 116, 0.2) 100%)"
                      : "linear-gradient(135deg, rgba(255, 255, 255, 0.05) 0%, rgba(255, 255, 255, 0.02) 100%)"
                  }}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <PCIcon />
                      <div>
                        <h3 className="text-white font-mona-sans text-xl font-bold mb-1">
                          {plan.name}
                        </h3>
                        <p className="text-white/40 font-sora text-sm">
                          {plan.description}
                        </p>
                      </div>
                    </div>

                    <div className="flex flex-col items-end gap-2">
                      {plan.isMostPopular && (
                        <MostPopularBadge />
                      )}
                      <div className="flex items-center gap-4">
                        <span className="text-white font-mona-sans text-3xl font-bold">
                          {plan.price}
                        </span>
                        
                        {/* Radio Input */}
                        <div 
                          className="w-10 h-10 rounded-full border flex items-center justify-center transition-all duration-300"
                          style={{
                            borderColor: "#FFFFFF",
                            borderWidth: "1px"
                          }}
                        >
                          {selectedPlan === plan.id && (
                            <div 
                              className="w-8 h-8 rounded-full transition-all duration-300"
                              style={{ background: "#A2CE3A" }}
                            />
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            {/* Right Side - Plan Details */}
            <motion.div
              initial={{ opacity: 0, x: 30 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.8, delay: 0.4 }}
              viewport={{ once: true }}
              className="rounded-[28px] p-6 lg:p-8"
              style={{
                background: "linear-gradient(135deg, rgba(162, 206, 58, 0.2) 0%, rgba(21, 99, 116, 0.2) 100%)",
                border: "0.5px solid #A2CE3A33"
              }}
            >
              <div className="mb-6">
                <h3 className="text-white font-mona-sans text-2xl font-bold mb-2">
                  {activePlan.name}
                </h3>
                <p className="text-4xl font-mona-sans font-bold text-white mb-4">
                  {activePlan.price}
                </p>
              </div>

              {/* Features List */}
              <div className="space-y-4 mb-8">
                {activePlan.features.map((feature, index) => (
                  <div key={index} className="flex items-start gap-3">
                    <CheckmarkIcon />
                    <span className="text-white/60 font-sora text-sm flex-1">
                      {feature}
                    </span>
                  </div>
                ))}
              </div>

              {/* Start Now Button */}
              <button
                onClick={handleStartNow}
                className="w-full px-8 py-4 rounded-[30px] font-mona-sans text-base font-semibold text-white hover:opacity-90 transition-opacity"
                style={{
                  background: "linear-gradient(90deg, #071522 25%, #A2CE3A 100%)",
                  boxShadow: "0px -6px 4px 0px #FFFFFF4D inset"
                }}
              >
                Start Now
              </button>
            </motion.div>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
